for _ in range(1000):
    N = rng.randint(6, 30)
    v = rng.randint(1, N-2)
    w = rng.randint(v+1, N-1)  # enforce v < w
    u = N - v
    t = N - w
    if u > 0 and t > 0:
        return {'u': u, 'v': v, 't': t, 'w': w}
# Fallback (extremely unlikely)
N = 10
v = 3
w = 6
u = N - v
t = N - w
return {'u': u, 'v': v, 't': t, 'w': w}

